CREATE OR REPLACE FUNCTION public.icash_owner_enrichment_retry_current(p_account uuid, p_screening uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s public.icash_screening_jobs;c public.icash_discovery_configs;r public.icash_operation_rates;stamp timestamptz;checked timestamptz:=clock_timestamp();cap bigint;
begin
 select * into s from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if not found or s.state<>'complete' or s.result->'financialCheck'->>'status' is distinct from 'eligible'
  or s.snapshot->>'propertyType' is distinct from 'house' or s.snapshot->'sellerRequest' is not null
  or coalesce(s.snapshot->>'practice','false')='true'
  or s.snapshot->>'propertyId' is null or s.snapshot->>'propertyId' !~ '^prop_[0-9]{1,20}$'
  or s.snapshot->'raw'->'data'->>'dm_property_id' is distinct from s.snapshot->>'propertyId'
  or not coalesce(public.icash_research_state_allowed(s.snapshot->'raw'->'data'->>'state'),false)
  or s.completed_at is null or s.completed_at<=checked-interval '24 hours' or s.completed_at>checked then return false;end if;
 begin stamp:=(s.snapshot->>'fetchedAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then return false;end;
 if stamp is null or stamp<=checked-interval '24 hours' or stamp>checked then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account;
 if not found or not c.enabled or not c.auto_enabled or not c.contacts_enabled or c.data_rights_until<=checked then return false;end if;
 select * into r from public.icash_operation_rates where id=c.contact_rate_id;
 if not found or not r.enabled or r.operation<>'owner_enrichment' or r.verified_at>checked or r.expires_at<=checked
  or jsonb_typeof(r.costs_micros->'dealmachine') is distinct from 'number'
  or c.contact_credit_cap::numeric*c.property_credit_micros>(r.costs_micros->>'dealmachine')::numeric then return false;end if;
 if not exists(select 1 from public.icash_operating_budget where id=1 and enabled)
  or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id
   where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
  or not coalesce(public.icash_membership_work_allowed(p_account),false)
  or public.icash_prospecting_available(p_account)<r.charge_cents
  or exists(select 1 from public.icash_billing_reviews where account_id=p_account and resolved_at is null)
  or exists(select 1 from public.icash_property_controls where account_id=p_account and property_id=s.snapshot->>'propertyId' and manual)
  or exists(select 1 from public.icash_owner_contacts oc join public.icash_screening_jobs prior on prior.id=oc.screening_id
   where oc.account_id=p_account and prior.snapshot->>'propertyId'=s.snapshot->>'propertyId' and oc.created_at>checked-interval '30 days') then return false;end if;
 select approved_max_charge_cents into cap from public.icash_owner_enrichment_recoveries where operation_key='owners:'||p_account||':'||p_screening;
 if found and r.charge_cents>cap then return false;end if;
 return coalesce(public.icash_owner_enrichment_unstarted(p_account,p_screening,'owners:'||p_account||':'||p_screening),false);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_acquisition()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;j uuid;t public.icash_automation_tickets;backlog integer;allowance bigint;minimum_quote bigint;continuation_enabled boolean:=false;continuation_turn boolean:=false;was_continuation boolean:=false;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 select enabled,(issued%3)<>2 into continuation_enabled,continuation_turn from icash_work_private.continuation_policy where id=1;
 -- Dedicated recovery owns account-scoped receipt settlement. A broken or
 -- busy historical receipt must not block selection for unrelated accounts.
 -- Keep the original sweep only for the compatible legacy dispatcher.
 if not exists(select 1 from icash_work_private.dispatch_policy where id=1 and enabled) then
  perform public.icash_settle_pending_dealmachine();
 end if;
 -- Expiry/exhaustion is terminal only for this exact proven-unstarted family.
 update public.icash_automation_tickets retry_ticket set outcome=case when owner_preview_deferrals>=8 then 'owner_preview_retry_exhausted' else 'owner_preview_expired' end
 where retry_ticket.kind='contacts' and retry_ticket.state='held' and retry_ticket.outcome='owner_preview_rate_limited'
 and (retry_ticket.owner_preview_deferrals>=8 or retry_ticket.owner_preview_retry_until<=clock_timestamp())
 and public.icash_owner_enrichment_unstarted(retry_ticket.account_id,retry_ticket.screening_id,'owners:'||retry_ticket.account_id||':'||retry_ticket.screening_id);
 update public.icash_automation_tickets set state='held',outcome='expired' where kind in ('contacts','discovery') and state='issued' and expires_at<=now();
 -- Leave other scheduler work available; billing and expiry checks above still run.

 for c in select d.* from public.icash_discovery_configs d join public.icash_accounts a on a.id=d.account_id join public.icash_wallets w on w.account_id=a.id
 left join icash_work_private.acquisition_export_waits export_wait on export_wait.account_id=d.account_id
 where d.enabled and d.auto_enabled and d.next_run_at<=now() and (public.icash_acquisition_capacity_available(d.account_id) or icash_work_private.owner_preflight_step_due(d.account_id)) and d.data_rights_until>now() and not a.bot_paused and w.balance_cents>w.reserved_cents
 and not exists(select 1 from public.icash_automation_tickets x where x.account_id=a.id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes')))
 order by
  -- Two continuation turns, then one ordinary turn, with work-conserving
  -- fallback. The existing five-row scan and budget lock remain authoritative.
  case when continuation_enabled then
   ((case when d.contacts_enabled and d.contact_rate_id is not null
     and (public.icash_owner_active_export_capacity(d.account_id) in ('disabled','ready') or icash_work_private.owner_preflight_step_due(d.account_id))
     then public.icash_owner_preflight_due_at(d.account_id,null::uuid) end is not null)=continuation_turn)
   end desc nulls last,
  -- Ordinary overdue accounts retain an aging escape from the due-list queue.
  case when coalesce(export_wait.waiting_since,d.next_run_at)<now()-interval '10 minutes' then coalesce(export_wait.waiting_since,d.next_run_at) end nulls last,
  public.icash_new_user_request_reserve_eligible(d.account_id) desc,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and (public.icash_owner_active_export_capacity(d.account_id) in ('disabled','ready') or icash_work_private.owner_preflight_step_due(d.account_id))
   then public.icash_owner_preflight_due_at(d.account_id,null::uuid) end nulls last,
  case when d.contacts_enabled and d.contact_rate_id is not null
   and (public.icash_owner_active_export_capacity(d.account_id) in ('disabled','ready') or icash_work_private.owner_preflight_step_due(d.account_id))
   then public.icash_owner_retry_due_at(d.account_id) end nulls last,
  (coalesce(export_wait.waiting_since,d.next_run_at)<now()-interval '5 minutes') desc,
  case when coalesce(export_wait.waiting_since,d.next_run_at)<now()-interval '5 minutes' then coalesce(export_wait.waiting_since,d.next_run_at) end,
  coalesce((public.icash_daily_work_target(d.account_id)->>'priorityRatio')::numeric,1),
  d.next_run_at,d.account_id limit 5 for update of d skip locked loop
 if icash_work_private.warm_seller_due(c.account_id) then
  update public.icash_discovery_configs set next_run_at=now()+interval '15 seconds' where account_id=c.account_id;
  continue;
 end if;
 perform public.icash_prepare_research_efficiency(c.account_id);
 select * into c from public.icash_discovery_configs where account_id=c.account_id;
 perform public.icash_refresh_opportunity_outcomes(c.account_id);
 if icash_work_private.record_export_wait(c.account_id,c.next_run_at) then continue;end if;
 allowance:=public.icash_prospecting_available(c.account_id);
 select min(quote) into minimum_quote from (
  select public.icash_research_admission_quote(c.account_id,'property_search',r.charge_cents) quote
   from public.icash_operation_rates r where r.id=c.rate_id
  union all
  select public.icash_research_admission_quote(c.account_id,'owner_enrichment',r.charge_cents)
   from public.icash_operation_rates r where c.contacts_enabled and (public.icash_owner_active_export_capacity(c.account_id) in ('disabled','ready') or icash_work_private.owner_preflight_step_due(c.account_id)) and r.id=c.contact_rate_id
 ) quotes;
 if minimum_quote is null or allowance<minimum_quote then
  if icash_work_private.record_export_wait(c.account_id,c.next_run_at) then continue;end if;
  delete from icash_work_private.acquisition_export_waits where account_id=c.account_id
   and public.icash_owner_active_export_capacity(c.account_id) in ('ready','disabled','export_busy');
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 j:=null;
 if c.contacts_enabled and c.contact_rate_id is not null then j:=public.icash_enrichment_candidate(c.account_id);end if;
 if j is not null then
 was_continuation:=continuation_enabled and public.icash_owner_preflight_due_at(c.account_id,j) is not null;
 delete from icash_work_private.acquisition_export_waits where account_id=c.account_id;
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind,screening_id) values(c.account_id,'contacts',j)
 on conflict(screening_id) do update set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=least(now()+interval '2 minutes',coalesce(public.icash_automation_tickets.owner_preview_retry_until,now()+interval '2 minutes')),issue_attempts=case when public.icash_automation_tickets.outcome='owner_preview_rate_limited' then public.icash_automation_tickets.issue_attempts else public.icash_automation_tickets.issue_attempts+1 end
 returning * into t;
 if continuation_enabled then perform icash_work_private.record_continuation_decision(t.id,c.account_id,t.screening_id,coalesce(was_continuation,false));end if;
 return jsonb_build_object('token',t.token);
 end if;
 -- Provider capacity remains bounded while completed attempts free the queue.
 backlog:=public.icash_pending_opportunity_count(c.account_id);
 if c.exhausted or backlog>=c.max_open_prospects or not public.icash_outbound_search_due(c.account_id) then
  if icash_work_private.record_export_wait(c.account_id,c.next_run_at) then continue;end if;
  delete from icash_work_private.acquisition_export_waits where account_id=c.account_id
   and public.icash_owner_active_export_capacity(c.account_id) in ('ready','disabled','export_busy');
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 -- A known inventory hold is not a new acquisition opportunity. Do not invoke
 -- the provider-facing discovery route repeatedly while its evidence is unchanged.
 -- Existing eligible contacts were selected above; retain their five-second cadence.
 -- Bound history by the indexed kind/created_at window and ignore future evidence.
 if exists(select 1 from public.icash_automation_tickets held
  where held.account_id=c.account_id and held.kind='discovery'
   and held.state='held' and held.outcome='inventory_held'
   and held.created_at between now()-interval '5 minutes' and now()
   and held.completed_at>now()-interval '60 seconds' and held.completed_at<=now()) then
  update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
  continue;
 end if;
 delete from icash_work_private.acquisition_export_waits where account_id=c.account_id;
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind) values(c.account_id,'discovery') returning * into t;
 if continuation_enabled then perform icash_work_private.record_continuation_decision(t.id,c.account_id,t.screening_id,coalesce(was_continuation,false));end if;
 return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION icash_work_private.record_continuation_decision(p_ticket uuid, p_account uuid, p_screening uuid, p_continuation boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare turn_number bigint;source_id uuid;issue_hash text;prior icash_work_private.continuation_decisions;
begin
 -- Match the scheduler lock order even for a direct service-role invocation.
 perform 1 from public.icash_operating_budget where id=1 for update;
 select encode(sha256(convert_to(token,'UTF8')),'hex') into issue_hash
  from public.icash_automation_tickets where id=p_ticket and account_id=p_account and state='issued'
   and screening_id is not distinct from p_screening and kind in ('contacts','discovery');
 if issue_hash is null or p_continuation is null then raise exception 'Continuation ticket changed';end if;
 select * into prior from icash_work_private.continuation_decisions where ticket_id=p_ticket and issue_token_hash=issue_hash;
 if found then
  if prior.account_id=p_account and prior.screening_id is not distinct from p_screening and prior.continuation=p_continuation then return;end if;
  raise exception 'Continuation issuance changed';
 end if;
 if not exists(select 1 from icash_work_private.continuation_policy where id=1 and enabled) then return;end if;
 if p_continuation then
  -- The ticket has just become issued, so rebind the source independently of
  -- the due helper's held-ticket predicate. Never select a stale sibling list.
  select p.id into source_id from icash_research_private.owner_export_preflights p
   where p.account_id=p_account and p.items->0->>'screeningId'=p_screening::text
    and ((p.state='waiting' and p.created_at>now()-interval '30 minutes' and p.created_at<=now()
      and p.next_check_at<=now() and p.deleted_at is null and p.cleanup_attempts=0)
     or (p.state='ready' and icash_research_private.owner_preflight_ready_current(p.id)))
    and icash_research_private.owner_preflight_list_known(p.id)
    and p.items=icash_research_private.owner_preflight_cohort(p_account,p_screening)
   order by case when p.state='ready' then p.checked_at else p.next_check_at end,p.created_at,p.id limit 1;
  if source_id is null then raise exception 'Continuation source changed';end if;
 end if;
 update icash_work_private.continuation_policy set issued=issued+1 where id=1 and enabled returning issued into turn_number;
 if not found then return;end if;
 insert into icash_work_private.continuation_decisions(ticket_id,account_id,screening_id,preflight_id,continuation,turn,issue_token_hash)
  values(p_ticket,p_account,p_screening,source_id,p_continuation,turn_number,issue_hash);
end $function$
